R area"><?php $this->load->view('pos/_icon', ['name' => 'edit', 'label' => 'Edit QR area']); ?></button><button type="button" class="btn btn-outline-secondary print-config-icon-btn <?= !empty($station['is_active']) ? 'is-danger' : 'is-success' ?>" data-station-toggle="<?= (int)$station['id'] ?>" title="<?= !empty($station['is_active']) ? 'Nonaktifkan QR' : 'Aktifkan QR' ?>" aria-label="Ubah status QR"><?php $this->load->view('pos/_icon', ['name' => 'power', 'label' => 'Ubah status']); ?></button><?php endif; ?></div></article><?php endforeach; ?></div><?php if ($canEdit): ?><div class="d-flex justify-content-end mt-3"><button type="button" class="btn btn-outline-primary" id="add-review-station"><?php $this->load->view('pos/_icon', ['name' => 'plus', 'label' => '']); ?><span class="ms-1">Tambah QR Area</span></button></div><?php endif; ?><?php endif; ?>
