<script>
document.addEventListener('DOMContentLoaded', function () {
  const ui = window.PrinterConfigUI; const canEdit = <?= $canEdit ? 'true' : 'false' ?>; const endpoint = '<?= site_url('pos/customer-reviews') ?>'; const body = document.getElementById('review-body'); const state = {q: '', status: 'ALL', date_from: '', date_to: '', page: 1, limit: 25};
  const reviewCsrf = <?= json_encode((string)($customer_review_csrf_token ?? ''), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
  const reviewCsrfHeader = <?= json_encode((string)($customer_review_csrf_header ?? ''), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
  async function postReview(path, payload) {
    if (!canEdit || !/^[a-f0-9]{64}$/.test(reviewCsrf) || reviewCsrfHeader !== 'X-Pos-Review-Csrf') {
      throw new Error('Sesi formulir ulasan tidak tersedia. Muat ulang halaman lalu coba kembali.');
    }
    const target = new URL(endpoint + path, window.location.href);
    if (target.origin !== window.location.origin) throw new Error('Alamat aplikasi tidak sesuai. Hubungi admin.');
    const response = await fetch(target.href, {
      method: 'POST', credentials: 'same-origin', mode: 'same-origin', redirect: 'error',
      headers: {'X-Requested-With': 'XMLHttpRequest', 'Content-Type': 'application/json', [reviewCsrfHeader]: reviewCsrf},
      body: JSON.stringify(payload || {})
    });
    const raw = await response.text();
    let result;
    try { result = JSON.parse(raw); } catch (error) {
      throw new Error('Jawaban server tidak dapat dibaca. Periksa sesi login lalu muat ulang halaman.');
    }
    if (!result || !response.ok || !result.ok) throw new Error((result && result.message) || 'Perubahan ulasan belum dapat disimpan.');
    return result;
  }
   function renderQr(container, url, size, label) { if (!container) return false; if (window.PosLocalQr && window.PosLocalQr.render(container, url, {size: size, label: label})) return true; container.textContent = 'QR belum dapat dimuat. Muat ulang halaman.'; return false; }
   document.querySelectorAll('[data-review-station-qr]').forEach(function (container) { renderQr(container, container.getAttribute('data-review-station-qr'), 220, container.getAttribute('aria-label') || 'QR ulasan pelanggan'); });
  function query() { return new URLSearchParams({review_q: state.q, review_status: state.status, review_date_from: state.date_from, review_date_to: state.date_to, review_page: state.page, review_limit: state.limit}).toString(); }
  function controls() { document.getElementById('review-q').value = state.q; document.getElementById('review-status').value = state.status; document.getElementById('review-date-from').value = state.date_from; document.getElementById('review-date-to').value = state.date_to; document.getElementById('review-limit').value = state.limit; }
  function badge(status) { const value = String(status || 'OPEN').toUpperCase(); const css = value === 'SUBMITTED' ? 'active' : (value === 'HIDDEN' ? 'inactive' : 'generated'); const text = value === 'SUBMITTED' ? 'Sudah masuk' : (value === 'HIDDEN' ? 'Disembunyikan' : 'Belum diisi'); return '<span class="print-config-status ' + css + '">' + text + '</span>'; }
  function stars(rating) { const n = Math.max(0, Math.min(5, Number(rating || 0))); return n ? '<span class="review-admin-stars">' + '&#9733;'.repeat(n) + '</span><span class="text-muted"> ' + n + '/5</span>' : '-'; }
  function actions(row) { if (!canEdit || String(row.review_status) === 'OPEN') return '-'; const hidden = String(row.review_status) === 'HIDDEN'; const title = hidden ? 'Tampilkan kembali ulasan' : 'Sembunyikan ulasan'; return '<button class="btn btn-outline-secondary print-config-icon-btn ' + (hidden ? 'is-success' : 'is-danger') + '" data-visibility="' + Number(row.id) + '" data-hidden="' + (hidden ? '0' : '1') + '" title="' + title + '" aria-label="' + title + '">' + ui.icon(hidden ? 'eye' : 'power', title) + '</button>'; }
  function source(row) { return String(row.review_source || 'RECEIPT') === 'STATION' ? 'QR area: ' + String(row.station_name || row.station_code || '-') : 'QR pada struk: ' + String(row.order_no_snapshot || row.order_no_live || '-'); }
  async function load() { controls(); const json = await ui.get(endpoint + '/data?' + query()); body.innerHTML = (json.rows || []).map(function (row) { const date = row.submitted_at || row.created_at || '-'; const customer = row.customer_name_snapshot || row.member_name || 'Walk in'; const comment = row.review_text ? ui.escapeHtml(row.review_text) : '<span class="muted">Belum ada isi ulasan.</span>'; return '<tr><td><strong>' + ui.escapeHtml(date) + '</strong><span class="review-list-source">' + ui.escapeHtml(source(row)) + '</span></td><td><strong>' + ui.escapeHtml(customer) + '</strong><div class="muted">' + ui.escapeHtml(row.outlet_name || '-') + '</div></td><td>' + stars(row.rating) + '</td><td><div class="review-admin-comment">' + comment + '</div></td><td>' + badge(row.review_status) + '</td><td class="text-center">' + actions(row) + '</td></tr>'; }).join('') || '<tr><td colspan="6" class="print-config-empty">Belum ada ulasan yang sesuai filter.</td></tr>'; ui.pager(document.getElementById('review-pager'), json.meta || {}, state, load); }
  document.getElementById('review-filter').addEventListener('click', function () { state.q = document.getElementById('review-q').value.trim(); state.status = document.getElementById('review-status').value; state.date_from = document.getElementById('review-date-from').value; state.date_to = document.getElementById('review-date-to').value; state.limit = Number(document.getElementById('review-limit').value); state.page = 1; load().catch(function (error) { ui.notice('error', 'Ulasan tidak dapat dimuat', error.message); }); });
  document.getElementById('review-clear').addEventListener('click', function () { state.q = ''; state.status = 'ALL'; state.date_from = ''; state.date_to = ''; state.page = 1; load().catch(function (error) { ui.notice('error', 'Ulasan tidak dapat dimuat', error.message); }); });
  body.addEventListener('click', async function (event) { const button = event.target.closest('[data-visibility]'); if (!button) return; const hidden = Number(button.dataset.hidden || 0) === 1; const action = hidden ? 'menyembunyikan' : 'menampilkan kembali'; if (!window.confirm('Yakin ingin ' + action + ' ulasan ini?')) return; try { await postReview('/visibility/' + Number(button.dataset.visibility), {hidden: hidden ? 1 : 0, reason: hidden ? 'Disembunyikan moderator melalui halaman ulasan.' : ''}); await load(); ui.notice('success', hidden ? 'Ulasan disembunyikan' : 'Ulasan ditampilkan', 'Status ulasan sudah diperbarui.'); } catch (error) { ui.notice('error', 'Status ulasan gagal diubah', error.message); } });
  const settings = document.getElementById('receipt-review-settings'); if (settings) settings.addEventListener('submit', async function (event) { event.preventDefault(); try { await postReview('/settings', {customer_review_qr_enabled: document.getElementById('receipt-review-enabled').checked ? 1 : 0, customer_review_message: document.getElementById('receipt-review-message').value.trim()}); const enabled = document.getElementById('receipt-review-enabled').checked; const badgeEl = document.getElementById('receipt-qr-status'); badgeEl.textContent = enabled ? 'Aktif' : 'Nonaktif'; badgeEl.className = 'print-config-status ' + (enabled ? 'active' : 'inactive'); ui.notice('success', 'Pengaturan QR struk disimpan', enabled ? 'QR akan muncul pada struk yang layout-nya mengizinkan.' : 'QR tidak akan muncul sampai diaktifkan kembali.'); } catch (error) { ui.notice('error', 'Pengaturan QR belum tersimpan', error.message); } });
  const stationModal = document.getElementById('review-station-modal'); const qrModal = document.getElementById('review-qr-preview-modal'); const stationForm = document.getElementById('review-station-form'); function openStation(data) { stationForm.reset(); document.getElementById('station-id').value = data.id || ''; document.getElementById('station-name').value = data.station_name || ''; document.getElementById('station-code').value = data.station_code || ''; document.getElementById('station-outlet').value = String(data.outlet_id || 0); document.getElementById('station-notes').value = data.notes || ''; document.getElementById('station-active').checked = data.is_active === undefined ? true : Number(data.is_active) === 1; document.getElementById('review-station-modal-title').textContent = data.id ? 'Edit QR Area' : 'Tambah QR Area'; stationModal.classList.add('is-open'); stationModal.setAttribute('aria-hidden', 'false'); document.getElementById('station-name').focus(); } function closeStation() { stationModal.classList.remove('is-open'); stationModal.setAttribute('aria-hidden', 'true'); } function closeQr() { qrModal.classList.remove('is-open'); qrModal.setAttribute('aria-hidden', 'true'); }
  const addStation = document.getElementById('add-review-station'); if (addStation) addStation.addEventListener('click', function () { openStation({}); }); document.querySelectorAll('[data-close-review-modal]').forEach(function (button) { button.addEventListener('click', closeStation); }); document.querySelectorAll('[data-close-qr-modal]').forEach(function (button) { button.addEventListener('click', closeQr); }); stationModal.addEventListener('click', function (event) { if (event.target === stationModal) closeStation(); }); qrModal.addEventListener('click', function (event) { if (event.target === qrModal) closeQr(); });
  document.querySelectorAll('[data-station-edit]').forEach(function (button) { button.addEventListener('click', function () { openStation(JSON.parse(button.dataset.stationEdit)); }); }); document.querySelectorAll('[data-station-preview]').forEach(function (button) { button.addEventListener('click', function () { const data = JSON.parse(button.dataset.stationPreview); const url = '<?= site_url('review/station/') ?>' + encodeURIComponent(String(data.station_code)); document.getElementById('review-qr-preview-title').textContent = String(data.station_name); document.getElementById('review-qr-preview-meta').textContent = String(data.outlet_name || 'Semua outlet') + ' - ' + String(data.station_code); renderQr(document.getElementById('review-qr-preview-image'), url, 520, 'QR ulasan ' + String(data.station_name)); document.getElementById('review-qr-print-link').href = endpoint + '/stations/print/' + Number(data.id); qrModal.classList.add('is-open'); qrModal.setAttribute('aria-hidden', 'false'); }); });
  if (stationForm) stationForm.addEventListener('submit', async function (event) { event.preventDefault(); if (!stationForm.reportValidity()) return; const submit = stationForm.querySelector('[type="submit"]'); submit.disabled = true; try { const data = ui.formObject(stationForm); data.is_active = document.getElementById('station-active').checked ? 1 : 0; await postReview('/stations/save', data); ui.notice('success', 'QR area disimpan', 'QR siap dilihat dan dicetak.'); window.setTimeout(function () { window.location.reload(); }, 350); } catch (error) { ui.notice('error', 'QR area belum tersimpan', error.message); } finally { submit.disabled = false; } });
  document.querySelectorAll('[data-station-toggle]').forEach(function (button) { button.addEventListener('click', async function () { try { await postReview('/stations/toggle/' + Number(button.dataset.stationToggle), {}); window.location.reload(); } catch (error) { ui.notice('error', 'Status QR belum diubah', error.message); } }); });
  load().catch(function (error) { body.innerHTML = '<tr><td colspan="6" class="print-config-empty">' + ui.escapeHtml(error.message) + '</td></tr>'; });
});
</script>
